def image_path(self, image):
    x = self.stem(image)
    return self.image_core(x)

def image_core(self, x):
    x = self.filter(x)
    x = torch.relu(x)
    x = self.pool(x)
    return x.flatten(1)

def vector_path(self, vector):
    x = self.lift(vector)
    return self.vector_core(x)
